scriptData.script:
// Expanded Criticals: Tyson Move grants Tyson Move: bitten off (generated by tools/grants.mjs).
const grant = async (id, value, key = this.item.system.location?.key) => {
  const item = await fromUuid(`Compendium.wfrp4e-core.items.Item.${id}`);
  if (!item) return ui.notifications.error(`Expanded Criticals: core item ${id} not found (is WFRP4e Core active?). Add it by hand.`);
  const data = item.toObject();
  // skipLocationValue keeps our display value ("5 Teeth", "Right Hand", "Nose") instead of the one derived from the key ("Head")
  let skipLocationValue = false;
  if (data.type === "injury" && data.system.location) {
    if (key) data.system.location.key = key;
    if (value) data.system.location.value = value;
    skipLocationValue = !!value || ["Teeth", "Nose", "Tongue", "Eye", "Ear"].includes(data.system.location.value);
  }
  return this.actor.createEmbeddedDocuments("Item", [data], {skipLocationValue});
};
const rollCount = async (formula, div = 1, add = 0, flavor) => {
  const roll = await new Roll(formula).evaluate({allowInteractive: false});
  if (flavor && /d/i.test(formula)) await roll.toMessage(this.script.getChatData({flavor}));
  return Math.max(1, Math.ceil(roll.total / div) + add);
};
const side = (s) => s === "Left" ? "l" : "r";
const lose = async (part, s) => {
  switch (part) {
    case "ear": return grant("8piWcBKFlQ2J1E3A", `${s} Ear`, side(s) + "Ear");
    case "eye": return grant("weczkAMPlTjX7lqU", `${s} Eye`, side(s) + "Eye");
    case "nose": return grant("SpPRZZRHxly7uo2G");
    case "teeth": { const n = await rollCount("1d10", 1, 0, "Teeth Lost"); return grant("fBcZhOBn8IpoVqQ1", `${n} Teeth`); }
  }
};
// 1-3 The nose, 4-8 One ear, 9-10 Cheek and/or lip: permanent -10 Fellowship
const r = (await new Roll("1d10").evaluate({allowInteractive: false}));
await r.toMessage(this.script.getChatData({flavor: "Tyson Move: what got bitten off"}));
if (r.total <= 3) await lose("nose");
else if (r.total <= 8) await lose("ear", (await new Roll("1d2").evaluate()).total === 1 ? "Left" : "Right");
else {
  const api = game.modules.get("artantares-advanced-criticals")?.api;
  const msg = "Cheek and/or lip bitten off: permanent -10 Fellowship (adjust the character's Fellowship).";
  if (api?.gmNote) await api.gmNote(this, msg); else ui.notifications.warn(msg);
}
